style.css:
@-moz-document domain("youtube.com") {
html, body {
        height: 100% !important;
        margin: 0 !important;
        padding: 0 !important;
        background: url('https://www.animeexplained.com/wp-content/uploads/2023/11/invincibles-all-marks-explained-e1699612838999.webp') no-repeat center center fixed !important;
        background-size: cover !important;
    }

    #content, ytd-app, ytd-page-manager, ytd-watch-flexy {
        background: transparent !important;
    }

    * {
        font-weight: bold !important;
        color: #ffffff !important;
        text-shadow: 2px 2px 5px rgba(0, 0, 0, 0.8) !important;
    }

    #video-title, h1.title, .ytd-video-primary-info-renderer {
        font-size: 20px !important;
        font-weight: bold !important;
        color: #ffcc00 !important;
        text-shadow: 3px 3px 6px rgba(0, 0, 0, 1) !important;
    }

    ytd-video-meta-block, span.ytd-video-meta-block, .style-scope {
        font-size: 16px !important;
        color: #f0f0f0 !important;
        text-shadow: 1px 1px 3px rgba(0, 0, 0, 0.6) !important;
    }

    ytd-thumbnail img {
        filter: brightness(1.1) contrast(1.2) !important;
    }
}
